def keep_demo(program, similar_problems):
    """program: a rationale rewritten as code.
    similar_problems: (input, gold) pairs that share the original logic
    but change its surface details."""
    for x, gold in similar_problems:
        try:
            if program(x) != gold:
                return False   # right once, wrong under intervention
        except Exception:
            return False
    return True                # the rationale transfers: keep it

demos = [d for d in candidates
         if d.correct and keep_demo(d.program, perturb(d.problem))]
